    body: "国立大学法人運営費交付金は、2004年の国立大学法人化以降、国が各国立大学法人に対して使途を特定せずに交付する基幹的な財源で、人件費や光熱費、施設維持費など教育研究活動の基盤を支える役割を担っています。\n\n法人化当初から、効率化を促す目的で毎年度一定割合を削減する「効率化係数」が適用された時期があり、運営費交付金は法人化後の10年余りで実質的に減少し、若手研究者の任期付きポストの増加や基盤的経費の逸迫を招いたとの指摘があります。\n\n近年は評価に基づく重点配分の割合が拡大しており、大学の機能強化や地域貢献などの取り組み実績に応じてメリハリをつけて配分する仕組みへと変化していますが、基盤的経費の安定的確保を求める大学側の声も根強くあります。",
