    summary:
      "1991年の大学設置基準改正で、一般教育・専門教育の科目区分を撤廃するなど基準を大幅に簡素化し、大学に教育課程編成の自由度を大きく与えた改革。",
    body: "大学設置基準の大綱化とは、1991年(平成3年)の大学設置基準改正によって行われた規制緩和を指す。それまでの大学設置基準は、卒業要件として一般教育科目・外国語科目・保健体育科目・専門教育科目という科目区分ごとに履修単位数を細かく定めており、これが硬直的なカリキュラム編成の一因とされていた。大綱化はこの科目区分を撤廃し、卒業に必要な単位数などの大枠のみを定めることで、各大学が自主的・自律的に教育課程を編成できるようにしたものである。\n\nこの改革の背景には、18歳人口の増加による大学進学者数の多様化、社会の変化に応じた柔軟な教育課程の必要性、そして大学の自己責任による質保証への転換という考え方があった。大綱化と同時に、大学は教育研究活動等の状況について自ら点検・評価を行い、その結果を公表する努力義務(自己点検・評価)を課されるようになり、事前規制から事後チェックへと質保証の仕組みが転換する契機ともなった。\n\n大綱化の結果、多くの大学で教養部が解体され、一般教育と専門教育を融合した新しいカリキュラムやリベラルアーツ型の学部再編が進んだ。一方で、教養教育(一般教育)の理念や体系性が失われ、専門教育偏重や教養教育の空洞化を招いたとの批判もあり、2000年代以降は教養教育の再構築が大学教育改革の重要課題として再び議論されるようになった。",
    relatedSlugs: ["jiko-tenken-hyoka", "taisho-kyoyoshugi", "daigaku-secchi-kijun"],
