    body: "学力の三要素とは、2007年の学校教育法改正(第30条第2項)で規定された学力の3つの構成要素、すなわち(1)基礎的な知識・技能、(2)これらを活用して課題を解決するために必要な思考力・判断力・表現力等、(3)主体的に学習に取り組む態度、を指す言葉である。もともとは初等中等教育の学力観として示されたものだが、高大接続改革の中でこの考え方が大学入学者選抜にも適用され、大学入試において育成・評価すべき能力の共通の物差しとして位置づけられるようになった。\n\n大学入学者選抜における文脈では、3つ目の要素はしばしば「主体性を持って多様な人々と協働して学ぶ態度」と表現され、文部科学省が毎年度発出する「大学入学者選抜実施要項」において、各大学は一般選抜・総合型選抜・学校推薦型選抜のいずれの入試区分においても、学力の三要素を大学ごとの特色に応じた方法・重み付けで多面的・総合的に評価することが求められている。具体的な評価材料としては、調査書(内申書)、学力検査(大学入学共通テストや個別試験)、小論文、面接、資格・検定試験の結果、活動報告書などが組み合わせて用いられる。\n\nこの考え方は、大学が策定するアドミッション・ポリシー(入学者受入れの方針)の根拠ともなっており、知識偏重とされてきた従来型の学力試験だけでなく、思考力や主体性といった非認知的な資質も含めて入学者を評価しようとする、大学入試改革全体の理念的な支柱となっている。一方で、主体性等の評価は測定の客観性や公平性の確保が難しいとの指摘もあり、評価方法の妥当性・信頼性をどう担保するかが引き続き課題とされている。",
