    body: "指定国立大学法人制度は、2016年の国立大学法人法改正により創設され、2017年度から運用が始まった制度である。世界最高水準の教育研究活動の展開が相当程度見込まれる国立大学法人を、文部科学大臣が「指定国立大学法人」として指定し、世界の有力大学と伍して競争できるよう、規制緩和や財政・運営面での特例措置を認めるものである。\n\n指定の対象は、研究力・国際化・ガバナンスなどの観点から一定の実績・計画を有する国立大学法人に限られ、各大学は指定にあたって「指定国立大学法人構想」を策定し、文部科学大臣の認定を受ける必要がある。特例措置としては、大学発ベンチャー等への出資対象の拡大、収益事業の範囲拡大、中期目標・中期計画に関する手続の弾力化などが認められている。2017年に東京大学・京都大学・東北大学、2018年に東京工業大学・名古屋大学・大阪大学、その後一橋大学・筑波大学・東京医科歯科大学・九州大学が順次指定され、2021年時点で10法人となっている。\n\n指定国立大学法人制度は、後に創設された国際卓越研究大学制度(大学ファンドによる助成)とは異なる枠組みであり、財政支援そのものよりも規制緩和による大学の自律的な経営力強化に主眼を置く点に特徴がある。両制度は重なり合う部分もありつつ、国立大学の世界的競争力強化という共通の政策目標のもとで、それぞれ異なるアプローチをとる施策として位置づけられている。",
