    summary:
      "10兆円規模の大学ファンドの運用益を長期・多額に助成する対象として文部科学大臣が認定する大学の制度。2024年に東北大学が第1号として認定された。",
    body: "国際卓越研究大学は、2022年制定の「国際卓越研究大学の研究等の体制強化及び研究開発等の推進に関する法律」に基づき、国際的に卓越した研究成果を生み出し、経済社会に大きな変化をもたらすことが相当程度見込まれる大学を文部科学大臣が認定する制度である。認定された大学は、科学技術振興機構(JST)が運用する10兆円規模の「大学ファンド」からの運用益を財源として、最長25年間にわたり年間数十億円から百億円規模の助成を受けることができる。\n\n認定を受けるには、国際的に卓越した研究の展開や事業成長を伴う経済社会への貢献が見込まれること、意思決定の合議体(運営方針会議)の設置など学長のリーダーシップと外部の視点を組み合わせたガバナンス体制を有すること、そして自己収入拡大に向けた事業成長への戦略を持つことなどが求められる。2022年12月から2023年3月にかけて実施された第1期公募には10大学が応募し、2023年9月に東北大学が唯一の認定候補に選定された。その後、体制強化計画の認可を経て、2024年11月に東北大学が国際卓越研究大学の第1号として正式に認定された。\n\nこの制度は、日本の大学の研究力が国際的に低下しているとの危機感を背景に、大学ファンドという新たな財政基盤を通じて、一部の大学に世界最高水準の研究大学へと飛躍する機会を集中的に与えようとするものである。一方で、助成対象が限られた大学に集中することへの懸念や、運営方針会議による外部関与の強化が大学の自治とどう両立するかといった論点も指摘されており、制度の運用は今後も注目されている。",
