    body: "大学ファンド(正式名称は「世界と伍する研究大学の実現のための大学ファンド」)は、日本の大学の研究力を国際的に高い水準へと引き上げることを目的として、科学技術振興機構(JST)が運用する約10兆円規模の基金である。政府出資金や財政投融資などを原資として2022年3月から本格的な資金運用が開始され、株式や債券への長期的な分散投資によって運用益を生み出し、その運用益を大学への助成に充てる仕組みとなっている。\n\nこのファンドの運用益は、国際卓越研究大学に認定された大学に対し、研究基盤の整備や若手研究者への投資などを目的として、最長25年間にわたり継続的に助成される。従来の科研費のような個別プロジェクト単位の競争的資金とは異なり、大学全体の研究基盤を長期・安定的に支える大規模な資金であることが特徴である。助成を受ける大学には、事業成長を通じた自己収入の拡大など、将来的な財政的自立に向けた戦略も求められる。\n\n大学ファンドの創設は、2021年に成立した改正科学技術・イノベーション基本法等を法的根拠とし、政府の「成長戦略」の一環として位置づけられている。もっとも、株式市場等での運用には価格変動リスクが伴うため、想定した運用益が安定的に確保できるかという点や、助成が一部の大学に集中することの是非をめぐって、制度創設当初から国会や有識者の間で議論が続けられてきた。",
