    body: "科目ナンバリング制度とは、大学の授業科目に、分野や水準(学部初年次向け・専門基礎・応用など)、履修順序を示す記号や番号を付与し、カリキュラム全体における各科目の位置づけを可視化する仕組みである。アメリカの大学で広く用いられている方式(例えば分野を示すアルファベットと難易度を示す数字を組み合わせた表記)を参考に、日本の大学でも2010年代以降、導入が進められてきた。\n\n科目ナンバリングの主な目的は、学生が自分の学修状況や目標に応じて、体系的に科目を選択できるようにすることにある。番号によって、その科目が基礎的な内容なのか発展的な内容なのか、どの科目を先に履修すべきかといった情報が一目で分かるようになり、学生の自律的な学修計画の作成を支援する。あわせて、シラバスとの連動により、教育課程全体の体系性(カリキュラムマップ)を教員・学生双方が把握しやすくなる効果もある。\n\nまた、科目ナンバリングは大学間の単位互換や留学時の単位認定を円滑にする役割も期待されている。番号の付け方が大学間である程度共通化されれば、他大学の科目がどの水準・分野に相当するかを比較しやすくなり、国内外の大学との学生交流を促進する基盤となりうる。文部科学省も大学教育の質的転換を進める答申の中で科目ナンバリングの活用を促しており、3ポリシーに基づく体系的なカリキュラム編成を可視化する手段の一つとして位置づけられている。",
