    body: "短期大学（短大）は、学校教育法に基づく大学の一種で、深く専門の学芸を教授研究し、職業または実際生活に必要な能力を育成することを主な目的とする。修業年限は2年または3年で、卒業者には2005年の学校教育法改正により「短期大学士」の学位が授与されるようになった（2006年3月卒業者から）。\n\n制度の出発点は戦後の学制改革である。1950年（昭和25年）4月の学校教育法の一部改正で、新制大学の基準を満たせない旧制専門学校などの受け皿として、短期大学は「暫定的な制度」として発足し、当初は149校だったとされる。その後、1962年に高等専門学校が創設されたことなどを背景に恒久化を求める声が高まり、1964年（昭和39年）6月の改正で本則に位置づけられ、卒業者の四年制大学への編入学も制度上認められた。\n\n短大は、とくに女性の高等教育機会の拡大や、保育・教育・家政・看護などの職業教育の担い手として大きな役割を果たしてきた。他方、1990年代半ば以降は四年制大学志向の高まりや18歳人口の減少を受けて学校数・入学者数は大きく減少し、四年制への改組や募集停止が相次いでいる。現在は、地域に根ざした職業教育機関としての再定義や、専門職大学・専門学校との関係の整理が課題となっている。",
    relatedSlugs: ["kosen", "senshu-gakko", "daigaku-secchi-kijun", "gakui-jusyo-kiko"],
