    body: "放送大学は、放送授業を中心に、学習センターでの面接授業やオンライン授業を組み合わせて学ぶ、放送大学学園が設置する大学である。働きながら学ぶ社会人、高校卒業後すぐの学生、高齢者など幅広い層が在籍し、学士の取得を目指す全科履修生のほか、特定の科目だけを履修する科目履修生や、学位を目的としない選科履修生など、多様な学び方が用意されている。\n\n沿革をたどると、1981年（昭和56年）に放送大学学園法が公布・施行され、特殊法人「放送大学学園」が発足した。大学そのものは1983年4月に設置され、1985年（昭和60年）4月から学生の受け入れが始まったとされる。放送大学学園法は2002年に全部改正され、2003年に新法が施行されている。全国各地に置かれた学習センター（学習拠点）で面接授業や学習相談が行われる点が、通信制大学としての特色である。\n\n放送大学は、生涯学習社会における大学の開放や、リカレント教育の受け皿としての意義が大きい。教員免許状の更新・取得や資格取得につながる科目群を持つなど、公的な学び直しの基盤でもある。近年はインターネット配信の拡充により、時間と場所の制約をさらに小さくする方向で発展している。",
