      "個々の大学では持てない大型の施設や資料を整備し、全国の研究者が共同で利用する研究機関。現在は4つの大学共同利用機関法人が運営する。",
    body: "大学共同利用機関は、全国の大学の研究者が共同して利用する研究施設や資料、データなどを整備し、大学単独では難しい大規模・長期の学術研究を支える国立の研究機関である。天文台、加速器、情報・統計、歴史民俗・民族学資料など、研究分野ごとに設けられ、共同利用・共同研究を通じて大学の研究力を下支えする点に特色がある。\n\n2004年の国立大学法人化に際して、国立大学法人法（2003年公布）に基づき、これらの機関は「大学共同利用機関法人」の下に再編された。現在は、人間文化研究機構、自然科学研究機構、高エネルギー加速器研究機構、情報・システム研究機構の4法人が置かれている。たとえば自然科学研究機構には国立天文台、情報・システム研究機構には国立情報学研究所や統計数理研究所などが属する。また、総合研究大学院大学は、これらの機関と連携して大学院教育を行う。\n\n大学共同利用機関は、一般の大学とは異なり学部教育を行わないが、大学院生の受け入れや共同研究の場を通じて人材養成にも関与している。研究大学と並ぶ日本の学術研究の基盤として、研究の「共同利用」という発想をどう維持・発展させるかが、研究評価や資源配分の議論と合わせて問われている。",
