    body: "URA（University Research Administrator）は、大学等において、研究者とともに研究プロジェクトの企画立案、研究資金の獲得支援、知的財産の管理、産学官連携、国際共同研究の調整などを担う専門職である。研究者が研究に専念できる環境を整えると同時に、組織としての研究戦略の立案を支える点で、教員でも事務職員でもない「第三の職種」と位置づけられてきた。\n\n日本では2010年代初頭から、文部科学省の事業等を通じて大学へのURAの配置・育成が進められてきた。文部科学省の産学官連携推進委員会ではスキル標準の整備や能力認定の在り方が議論され、その後、2019年度からの検討・試行を経て、2021年度から研修と認定URAの審査が始まったとされる。認定は一般社団法人リサーチ・アドミニストレータースキル認定機構が行い、研修の運用は2024年度からJSTが引き継いでいる。\n\n課題としては、雇用の多くが有期である点、キャリアパスや処遇の不透明さ、大学ごとの役割の違いなどが指摘されてきた。国際卓越研究大学や大学ファンドなど研究力強化政策が進むなか、URAは研究大学のガバナンスや戦略形成を支える重要な人材として、あらためて注目されている。",
