    body: "インターンシップは、学生が在学中に企業や官公庁、NPOなどで、自分の専攻や将来のキャリアに関連した就業体験を行う取り組みである。大学教育にとっては、実社会での経験を通じて学習の動機づけを高め、キャリア意識を育む場として位置づけられてきた。日本では1990年代後半から、文部科学省・厚生労働省・経済産業省の三省が「インターンシップの推進に当たっての基本的考え方」（三省合意）を示して普及を後押ししてきた。\n\n2022年6月に三省合意が改正され、「採用と大学教育の未来に関する産学協議会」の報告書を受けて、学生のキャリア形成支援の取り組みが4類型に整理された。タイプ1がオープン・カンパニー、タイプ2がキャリア教育、タイプ3が汎用的能力・専門活用型インターンシップ、タイプ4が高度専門型インターンシップ（試行）である。一定期間の就業体験を伴うタイプ3・タイプ4のみが「インターンシップ」と呼ばれ、これらで得た学生の情報は、要件を満たす場合に採用選考に活用することが認められるようになった。タイプ3では、汎用的能力活用型は5日間以上、専門活用型は2週間以上とされている。\n\n課題としては、実質的な採用の早期化への懸念、教育的な効果と採用活動の線引き、学業との両立、参加機会の格差、短期プログラムの質などが指摘される。大学側には、事前・事後学習を含む正課教育との接続と、単位認定の質保証が求められている。",
