    body: "地（知）の拠点整備事業（大学COC事業、Center of Community）は、大学が自治体等と連携し、全学的に地域を志向した教育・研究・社会貢献を進めることを支援するため、文部科学省が2013年度に開始した事業である。地域課題の解決に取り組むことを大学の中核的な役割の一つとして位置づけ、地域をフィールドとする教育プログラムや、地域住民・自治体との連携体制の整備を促した。採択された大学の助成期間は、琉球大学の報告書によれば2013年度から2017年度の5年間であった。\n\n2015年度には、これを発展させた「地（知）の拠点大学による地方創生推進事業（COC+）」が始まった。COC+は、大学が地方公共団体や企業等と協働して地域に雇用を創出し、地元で働く人材を育成することをねらいとし、地元への就職や定着を促す点に特色がある。2015年度は56件の申請から42件の事業が選定されたとされる。\n\nこれらの事業を通じて、地域連携が大学の評価や教育プログラムに組み込まれ、地域志向科目や地域課題解決型学習（PBL）、サービスラーニングが広がった。事業終了後の持続可能性や、地域貢献の評価指標、大学の機能別分化との関係が論点となっている。",
