    categories: ["higher-ed", "philosophy"],
    summary:
      "実存哲学者K・ヤスパースの大学論。1923年版を戦後の1946年に改訂し、研究・教授・教養の統一として大学を論じた。",
    body: "カール・ヤスパースは、ドイツの哲学者・精神医学者で、実存哲学の代表者として知られる。『大学の理念（Die Idee der Universität）』は、1923年に刊行されたのち、ナチス体制下の大学の経験を踏まえて戦後の1946年に改訂版（Springer社）が出された。さらに1961年には、共著者のロスマンとともに大幅に書き直された版が出されたとされる。戦後版の英訳は1959年にビーコン・プレスから刊行されている。\n\nヤスパースの大学論は、大学を真理の探究を中心とする共同体として捉える点に特色がある。研究と教授、そして人格的な教養とを分けずにとらえ、知識の専門分化を超えて学問全体の連関を意識させるべきだとし、学問の自由の保障を大学の根本条件と位置づけた。国家や社会が大学を支援する一方で、大学は真理への奉仕という独自の原理に立たなければならないという立場である。\n\nフンボルト理念を引き継ぐ側面を持ちつつ、ナチス時代の大学の経験を踏まえ、大学と政治・社会との緊張関係を深く考察した点が評価される。現代の大学が市場や政策の要請にさらされるなかで、大学の自律と学問の使命を問い直す際に、しばしば参照される古典である。",
    relatedSlugs: ["humboldt-rinen", "newman-daigaku-no-rinen", "daigaku-jichi-no-rekishi", "jitsuzon-shugi-kyoiku"],
