    body: "『職業としての学問』は、社会学者マックス・ウェーバーが第一次世界大戦末期の1917年11月、ミュンヘン大学で学生向けに行った講演をもとにした著作で、1919年に刊行された。1919年1月の講演『職業としての政治』と対をなす作品として、岩波文庫などで読み継がれている。邦題は「仕事としての学問」と訳される新訳もある。\n\n講演は、大学教員の外的な条件、すなわち就職の不確実性から始まる。ドイツでは私講師（無給）から出発して教授を目指す道に偶然（運）の要素が大きく、アメリカの助教授制度と比べて不安定であることを指摘する。そのうえで、学問に専心する内的な条件として、専門化の徹底と「情熱」「着想（ひらめき）」を挙げ、学問の進歩が合理化・主知化（脱魔術化）をもたらす一方、「われわれはいかに生きるべきか」という問いには答えを与えないことを論じた。教壇では価値判断を持ち込まない姿勢（価値自由）が教師に求められる、という議論でもよく知られる。\n\nこの講演は、大学教員のキャリア、研究と教育の関係、学問の自由と教員の責任といった問題を考えるための古典とされる。現代の研究者の有期雇用化やテニュアトラック制度の議論にも通じる論点を含んでおり、高等教育研究や学問論でしばしば参照される。",
