    body: "学士力とは、2008年（平成20年）12月の中央教育審議会答申「学士課程教育の構築に向けて」で示された、学士課程共通の学習成果に関する参考指針である。専攻分野を通じて培う能力として、国が大学の教育改革の指針として提示したものであり、各大学が学位授与方針（ディプロマ・ポリシー）を定める際の参考とされた。\n\n学士力は4つの分野から構成される。（1）知識・理解（多文化・異文化に関する知識の理解、人類の文化、社会と自然に関する知識の理解）、（2）汎用的技能（コミュニケーション・スキル、数量的スキル、情報リテラシー、論理的思考力、問題解決力）、（3）態度・志向性（自己管理力、チームワーク・リーダーシップ、倫理観、市民としての社会的責任、生涯学習力）、（4）統合的な学習経験と創造的思考力、である。同答申は、教育課程の体系化、学習成果の重視、高大接続や入学者選抜の改善なども提言した。\n\n学士力は、大学教育を「何を教えたか」から「何ができるようになったか」へ転換する流れを促し、3つのポリシーや学修成果の可視化、アセスメントの議論と結びついた。一方、経済界の求める「社会人基礎力」などとの重なりや、国が能力像を示すことへの批判もある。教養教育や専門教育との関係をどう整理するかも継続的な論点である。",
