    body: "大学の入学者選抜区分の一つで、従来の「一般入試」に相当する選抜方法である。高大接続改革に伴い、従来の教科・科目に係るペーパーテストによる知識・技能の評価偏重を改め、「思考力・判断力・表現力」や「主体性を持って多様な人々と協働して学ぶ態度」を含めた学力の3要素を多面的・総合的に評価することが求められている。\n\n文部科学省の「大学入学者選抜実施要項」に基づき、大学入学共通テストの成績や各大学が独自に課す個別学力検査、小論文、面接、調査書などを組み合わせて判定を行う。出願時期は例年1月以降に設定され、国公立大学では前期日程・後期日程などの分離分割方式で実施される。\n\n近年では、一般選抜においても調査書の点数化や志望理由書・活動報告書の提出を求める大学が増加しており、学力検査の得点のみならず高校での多様な学習活動の実績を総合的に考慮した公正・妥当な選抜の実現が目指されている。",
