    body: "学校教育法第84条に基づき、大学が通信による授業を行う制度である。1947年の学校教育法制定とともに制度化され、1950年に文部省により正式認可された。地理的・時間的制約や経済的理由から通学が困難な勤労者、社会人、家庭責任を持つ者、地方在住者等に対し、高等教育を受ける機会を広く開放する役割を担ってきた。\n\n教育方法としては、テキストを用いた印刷教材による通信指導、大学の教室等で受講する面接授業（スクーリング）、放送大学等の放送授業に加え、近年ではインターネットを活用したメディア授業が急速に発展している。一定の基準を満たすメディア授業を履修することで、通学制と同様に卒業要件単位を満たし学士号を取得できる。\n\n生涯学習ニーズの高度化やリカレント教育の推進に伴い、教職課程をはじめとする資格取得や教養深化を目指す多様な年齢層の学修者を支える柔軟な高等教育システムとして位置づけられている。",
