    body: "大学に置かれる教員の合議制機関であり、学校教育法第93条にその設置が規定されている。各学部や研究科等の教育研究に関する重要事項を審議し、大学の教育研究水準を維持・向上させる役割を担う伝統的な自治組織である。\n\n2014年（平成26年）の学校教育法改正により、教授会の位置づけが大きく見直された。改正前は教授会が大学の実質的な最高意思決定機関として機能し、意思決定の遅延や組織の硬直化を招いているとの指摘があったため、学長が「教育研究に関する事項で審議が必要なもの」について意見を聴く審議機関であることが法令上明確化された。\n\n教授会が意見を述べる事項としては、学生の入学・卒業・課程の修了、学位の授与、教育課程の編成などが定められている。学長を中心とするガバナンス体制と、現場の教員による教育研究の専門的判断の調和が図られている。",
