    body: "アドミッション・ポリシー（AP）は、大学や学部・学科が教育理念やディプロマ・ポリシー、カリキュラム・ポリシーを踏まえ、入学時にどのような資質・能力、学力、学習意欲を持った学生を求めているかを公表した基本方針である。\n\n方針では、高等学校段階で修得しておくべき知識・技能、思考力・判断力・表現力、主体的な学習態度などが明示される。さらに、これらの資質を評価するために、一般選抜、学校推薦型選抜、総合型選抜の各入試区分で何をどのように測るのかという選抜方法との連動が示される。\n\n明確なAPの提示は、高校生が自らの進路や興味と合致する大学を選択するミスマッチの防止につながる。高大接続改革の柱として、高校教育と大学教育の円滑な接続を保証する入り口の機能として重要な意義を持つ。",
