    body: "厳格な成績評価基準は、教員個人の主観による成績の甘さや厳しさのばらつき（成績インフレ・デフレ）を是正し、大学全体としての単位の信用性を担保するための全学的ガイドラインである。認証評価や教学マネジメント指針において強く推奨されている。\n\nガイドラインでは、秀（S）、優（A）、良（B）、可（C）、不可（F）などの評語に対応する達成水準を明確化し、ルーブリックを用いた到達度評価の導入を促す。さらに、多人数クラス等においては上位評語（SやA）の割合に一定の目安（例えば30％以内など）を設定し、分布の偏りを管理する。\n\n成績評価の分布データは学内で集計・開示され、教員間の相互検証やFDの題材として活用される。客観的で公平な成績評価は、学生の納得感を高めるとともに、国内外の企業や大学院に対して学位の信頼性を保証する基盤となる。",
