    body: "卒業論文・研究の評価ルーブリックは、学士課程教育の総括的な学修成果を測定する卒業研究において、評価の観点と達成水準を明確に言語化したマトリクス形式の評価基準表である。指導教員の主観に偏りがちであった従来の審査方法を客観化する。\n\n評価の観点には、課題設定の妥当性、先行研究の調査力、論理的構成力、研究手法の適切性、論文執筆の作法、口頭発表での質疑応答力などが設定される。各観点について「優秀・良好・合格・不合格」などの基準が具体的に記述され、主査・副査が共通基準で採点する。\n\nルーブリックを事前に学生に公開することで、学生自身が研究の目標と執筆水準を自覚して計画的に論文作成に取り組むことができる。ディプロマ・ポリシーの達成度を測定する中核的ツールとして、各大学の学部で広く導入されている。",
