    body: "技術移転機関（TLO：Technology Licensing Organization）は、1998年に制定された大学等技術移転促進法に基づき、大学の研究成果（特許や実用新案等）を発掘・権利化し、民間企業へ技術移転（ライセンス供与）を行う専門機関である。\n\n研究者から発明の届出を受け、特許性の調査や国内外での特許出願手続きを代行する。さらに、その技術を必要とする企業を探索してライセンス契約を締結し、得られた特許料（ロイヤルティ）を発明者や大学に配分して次の研究開発資金として還流させる。\n\n大学の象牙の塔からの脱却と、日本の産業競争力の強化を意図して創設された。大学発の先端技術を迅速に社会実装し、新産業の創出とイノベーションを駆動する産学連携の中核エンジンとして機能している。",
