    body: "大学の社会的責任（USR：University Social Responsibility）は、大学が教育研究の推進だけでなく、社会の一員として倫理的、環境的、社会的な課題に対して積極的な貢献と説明責任を果たすべきであるとする現代的な理念である。\n\n具体的には、キャンパスにおける省エネルギー化や脱炭素化の推進、ダイバーシティ＆インクルージョンの確立、公平な労務管理、研究成果のオープン化、SDGs（持続可能な開発目標）の達成に向けた学際的研究や教育プログラムの提供などが含まれる。年次で「USR報告書」を公表する大学も多い。\n\n大学が社会的良心のモデルとなり、持続可能な未来社会を創造する先導者としての役割を果たすことが求められている。地域社会や国際社会からの高い信頼を獲得し、大学のブランド価値と存在意義を高める現代高等教育の重要指針である。",
